<?php

declare(strict_types=1);

namespace App\Play\Domain\Campaign\Facts;

/**
 * The campaign already holds a Campaign fact with this id. Ids are generated by the caller, so a
 * repeated command must not replace the existing fact.
 */
final class FactAlreadyExists extends \DomainException
{
    public static function withId(FactId $id): self
    {
        return new self(\sprintf('Fact "%s" already exists.', $id->toString()));
    }
}
